import { Page, SSGOptions } from './types';

export interface BuildContext {
  options: SSGOptions;
  pages: Page[];
  outputDir: string;
  templateDir?: string;
  [key: string]: any;
}

export interface Plugin {
  name: string;
  onStart?(context: BuildContext): void | Promise<void>;
  beforeBuild?(context: BuildContext): void | Promise<void>;
  onFile?(page: Page, context: BuildContext): void | Promise<void>;
  afterBuild?(context: BuildContext): void | Promise<void>;
  onEnd?(context: BuildContext): void | Promise<void>;
}

export interface SSGConfig {
  plugins?: (string | { name: string; options?: Record<string, any> })[];
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { Plugin, BuildContext } from '../plugin';
import { Page } from '../types';

function slugify(filename: string): string {
  const name = path.basename(filename, path.extname(filename));
  return name.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
}

function readMarkdownFiles(contentDir: string): string[] {
  if (!fs.existsSync(contentDir)) {
    return [];
  }
  return fs.readdirSync(contentDir)
    .filter(f => f.endsWith('.md'))
    .map(f => path.join(contentDir, f));
}

function parsePage(filePath: string): Page {
  const raw = fs.readFileSync(filePath, 'utf-8');
  const { data, content } = matter(raw);
  const html = marked.parse(content) as string;
  const slug = slugify(path.basename(filePath));
  return {
    frontmatter: {
      title: data.title || slug,
      date: data.date,
      tags: data.tags,
      template: data.template,
      layout: data.layout,
    },
    html,
    slug,
  };
}

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  beforeBuild(context: BuildContext): void {
    const { contentDir } = context.options;
    const files = readMarkdownFiles(contentDir);
    for (const file of files) {
      const page = parsePage(file);
      context.pages.push(page);
    }
  }
}

import fs from 'fs';
import path from 'path';
import { Plugin, BuildContext } from '../plugin';
import { Page, PageTemplateData } from '../types';
import { TemplateEngine } from '../template-engine';

function toTemplateData(page: Page): PageTemplateData {
  const { title, date, tags } = page.frontmatter;
  return {
    title,
    date,
    dateFormatted: date ? new Date(date).toLocaleDateString('en-US') : undefined,
    tags,
    tagsStr: tags && tags.length > 0 ? tags.join(', ') : undefined,
    content: page.html,
    slug: page.slug,
  };
}

export class TemplatePlugin implements Plugin {
  name = 'template';
  private engine: TemplateEngine | null = null;

  onStart(context: BuildContext): void {
    const { templateDir } = context.options;
    this.engine = new TemplateEngine(templateDir);
  }

  onFile(page: Page, context: BuildContext): void {
    if (!this.engine) return;

    const data = toTemplateData(page);
    const pageHTML = this.engine.renderPage(data, page.frontmatter.template, page.frontmatter.layout);
    const outPath = path.join(context.outputDir, `${page.slug}.html`);
    fs.writeFileSync(outPath, pageHTML, 'utf-8');
  }

  afterBuild(context: BuildContext): void {
    if (!this.engine) return;

    const indexData = {
      title: 'My Static Site',
      pages: context.pages.map(toTemplateData),
    };
    const indexHTML = this.engine.renderIndex(indexData);
    fs.writeFileSync(path.join(context.outputDir, 'index.html'), indexHTML, 'utf-8');
  }
}

import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar, { FSWatcher } from 'chokidar';
import { Plugin, BuildContext } from '../plugin';
import { SSGEngine } from '../ssg';

export interface DevServerOptions {
  contentDir: string;
  outputDir: string;
  templateDir?: string;
  port: number;
}

export interface ServeInstance {
  server: http.Server;
  watcher: FSWatcher;
  wss: WebSocketServer;
}

const LIVE_RELOAD_SCRIPT = `<script>(function(){var w=new WebSocket('ws://'+location.host);w.onmessage=function(e){if(e.data==='reload')location.reload()}})();</script>`;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html',
  '.css': 'text/css',
  '.js': 'text/javascript',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml',
};

function injectLiveReload(html: string): string {
  if (html.includes('</body>')) {
    return html.replace('</body>', LIVE_RELOAD_SCRIPT + '</body>');
  }
  return html + LIVE_RELOAD_SCRIPT;
}

export class DevServerPlugin implements Plugin {
  name = 'dev-server';
  private engine: SSGEngine | null = null;
  private instance: ServeInstance | null = null;

  setEngine(engine: SSGEngine): void {
    this.engine = engine;
  }

  start(options: DevServerOptions): ServeInstance {
    const { contentDir, outputDir, templateDir, port } = options;

    const server = http.createServer((req, res) => {
      const url = req.url === '/' ? '/index.html' : req.url || '/';
      const filePath = path.join(outputDir, url);

      if (fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
        const ext = path.extname(filePath);
        const contentType = MIME_TYPES[ext] || 'application/octet-stream';

        let content = fs.readFileSync(filePath, 'utf-8');

        if (ext === '.html') {
          content = injectLiveReload(content);
        }

        res.writeHead(200, { 'Content-Type': contentType });
        res.end(content);
      } else {
        res.writeHead(404);
        res.end('Not found');
      }
    });

    const wss = new WebSocketServer({ server });

    const clients = new Set<WebSocket>();

    wss.on('connection', (ws) => {
      clients.add(ws);
      ws.on('close', () => clients.delete(ws));
    });

    function notifyClients() {
      for (const client of clients) {
        if (client.readyState === WebSocket.OPEN) {
          client.send('reload');
        }
      }
    }

    const watchDirs: string[] = [];
    if (fs.existsSync(contentDir)) {
      watchDirs.push(contentDir);
    }
    if (templateDir && fs.existsSync(templateDir)) {
      watchDirs.push(templateDir);
    }

    const watcher = chokidar.watch(watchDirs, {
      ignoreInitial: true,
      awaitWriteFinish: { stabilityThreshold: 100, pollInterval: 50 },
    });

    const engine = this.engine;

    function rebuild() {
      try {
        if (engine) {
          engine.build();
        }
        notifyClients();
      } catch (err) {
        // nop
      }
    }

    watcher.on('change', rebuild);
    watcher.on('add', rebuild);
    watcher.on('unlink', rebuild);

    server.listen(port, () => {
      console.log(`Dev server running at http://localhost:${port}`);
    });

    this.instance = { server, watcher, wss };
    return this.instance;
  }

  getInstance(): ServeInstance | null {
    return this.instance;
  }
}

import { SSGConfig } from './src/plugin';

const config: SSGConfig = {
  plugins: ['markdown', 'template'],
};

