import fs from 'fs';
import path from 'path';
import { Plugin, BuildContext, SSGConfig } from './plugin';
import { SSGOptions } from './types';
import { MarkdownPlugin } from './plugins/markdown-plugin';
import { TemplatePlugin } from './plugins/template-plugin';

export class SSGEngine {
  private plugins: Plugin[] = [];
  private options: SSGOptions;

  constructor(options: SSGOptions) {
    this.options = options;
    this.loadPlugins();
  }

  private loadPlugins(): void {
    this.plugins.push(new MarkdownPlugin());
    this.plugins.push(new TemplatePlugin());

    try {
      const configPath = path.resolve('ssg.config.ts');
      if (fs.existsSync(configPath)) {
        const resolved = this.resolveConfig();
        if (resolved && resolved.plugins) {
          for (const entry of resolved.plugins) {
            if (typeof entry === 'string') {
              const plugin = this.loadPluginModule(entry);
              if (plugin && !this.plugins.some(p => p.name === plugin.name)) {
                this.plugins.push(plugin);
              }
            }
          }
        }
      }
    } catch {
      // Config loading is best-effort
    }
  }

  private resolveConfig(): SSGConfig | null {
    try {
      const configPath = path.resolve('ssg.config.ts');
      const { registry } = require('ts-node')?.register?.() || {};
    } catch {}
    try {
      const configPath = path.resolve('ssg.config.js');
      if (fs.existsSync(configPath)) {
        const cfg = require(configPath);
        return cfg.default || cfg;
      }
    } catch {}
    return null;
  }

  private loadPluginModule(name: string): Plugin | null {
    try {
      const mod = require(path.resolve(name));
      const PluginClass = mod.default || mod[name + 'Plugin'] || mod;
      if (typeof PluginClass === 'function') {
        const instance = new PluginClass();
        if (instance.name && typeof instance.onStart !== 'undefined' || typeof instance.beforeBuild !== 'undefined' || typeof instance.onFile !== 'undefined' || typeof instance.afterBuild !== 'undefined' || typeof instance.onEnd !== 'undefined') {
          return instance;
        }
      }
      return null;
    } catch {
      return null;
    }
  }

  build(): void {
    const { outputDir, templateDir } = this.options;

    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    const context: BuildContext = {
      options: this.options,
      pages: [],
      outputDir,
    };

    for (const plugin of this.plugins) {
      if (plugin.onStart) {
        plugin.onStart(context);
      }
    }

    for (const plugin of this.plugins) {
      if (plugin.beforeBuild) {
        plugin.beforeBuild(context);
      }
    }

    for (const page of context.pages) {
      for (const plugin of this.plugins) {
        if (plugin.onFile) {
          plugin.onFile(page, context);
        }
      }
    }

    for (const plugin of this.plugins) {
      if (plugin.afterBuild) {
        plugin.afterBuild(context);
      }
    }

    for (const plugin of this.plugins) {
      if (plugin.onEnd) {
        plugin.onEnd(context);
      }
    }
  }
}

export function build(options: SSGOptions): void {
  const engine = new SSGEngine(options);
  engine.build();
}

